// Some portions generated by Claude
package org.eclipse.rdf4j.rio.rdfxml;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayOutputStream;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.Collection;

import javax.xml.parsers.DocumentBuilderFactory;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.RDFParser;
import org.eclipse.rdf4j.rio.RDFWriter;
import org.eclipse.rdf4j.rio.Rio;
import org.eclipse.rdf4j.rio.helpers.StatementCollector;
import org.junit.jupiter.api.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.xml.sax.InputSource;

/**
 * Verifies that XML literals (rdf:parseType="Literal") are self-contained: every namespace binding inherited from the
 * literal's context that is used inside the literal is declared, and nothing else.
 */
class RDFXMLLiteralNamespaceTest {

	@Test
	void inheritedPrefixUsedOnlyByAttributeIsIncludedInXmlLiteral() throws Exception {
		Literal literal = parseXmlLiteral("<div a:flag=\"value\"/>", "xmlns:a=\"urn:attribute:\"");

		Element div = (Element) parseFragment(literal.stringValue()).getElementsByTagName("div").item(0);
		assertThat(div.getAttributeNodeNS("urn:attribute:", "flag")).isNotNull();
	}

	@Test
	void inheritedPrefixUsedOnlyByNestedAttributeIsIncludedInXmlLiteral() throws Exception {
		Literal literal = parseXmlLiteral("<div><span a:flag=\"value\"/></div>", "xmlns:a=\"urn:attribute:\"");

		Element span = (Element) parseFragment(literal.stringValue()).getElementsByTagName("span").item(0);
		assertThat(span.getAttributeNodeNS("urn:attribute:", "flag")).isNotNull();
	}

	@Test
	void inheritedPrefixUsedOnlyByAttributeSurvivesWriterRoundTrip() throws Exception {
		Statement statement = parseXmlLiteralStatement("<div a:flag=\"value\"/>", "xmlns:a=\"urn:attribute:\"");
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		RDFWriter writer = Rio.createWriter(RDFFormat.RDFXML, output);
		writer.startRDF();
		writer.handleStatement(statement);
		writer.endRDF();

		Collection<Statement> roundTripped = parse(output.toString(StandardCharsets.UTF_8));
		assertThat(roundTripped).hasSize(1);
	}

	@Test
	void xmlPrefixIsNeverDeclaredInXmlLiteral() throws Exception {
		Literal literal = parseXmlLiteral("<div xml:lang=\"en\"/>", "");

		assertThat(literal.stringValue()).doesNotContain("xmlns:xml");
		assertThat(parseFragment(literal.stringValue()).getElementsByTagName("div").getLength()).isEqualTo(1);
	}

	@Test
	void inheritedPrefixUsedByElementRemainsSelfContained() throws Exception {
		Literal literal = parseXmlLiteral("<a:group><a:child/></a:group>", "xmlns:a=\"urn:element:\"");

		Document document = parseFragment(literal.stringValue());
		assertThat(document.getElementsByTagNameNS("urn:element:", "group").getLength()).isEqualTo(1);
		assertThat(document.getElementsByTagNameNS("urn:element:", "child").getLength()).isEqualTo(1);
	}

	@Test
	void inheritedPrefixIsInjectedIntoSiblingRootsAfterNestedContent() throws Exception {
		Literal literal = parseXmlLiteral("<p:a><b/></p:a><p:c/>", "xmlns:p=\"urn:outer:\"");

		Document document = parseFragment(literal.stringValue());
		assertThat(document.getElementsByTagNameNS("urn:outer:", "a").getLength()).isEqualTo(1);
		assertThat(document.getElementsByTagNameNS("urn:outer:", "c").getLength())
				.as("XMLLiteral: %s", literal.stringValue())
				.isEqualTo(1);
	}

	@Test
	void locallyDeclaredPrefixKeepsItsScopeAcrossSiblingRoots() throws Exception {
		Literal literal = parseXmlLiteral(
				"<box xmlns:p=\"urn:inner:\"><p:inside/></box><p:outside/>",
				"xmlns:p=\"urn:outer:\"");

		Document document = parseFragment(literal.stringValue());
		assertThat(document.getElementsByTagNameNS("urn:inner:", "inside").getLength()).isEqualTo(1);
		assertThat(document.getElementsByTagNameNS("urn:outer:", "outside").getLength())
				.as("XMLLiteral: %s", literal.stringValue())
				.isEqualTo(1);
	}

	@Test
	void defaultNamespaceUndeclarationDoesNotLeakToFollowingSibling() throws Exception {
		Literal literal = parseXmlLiteral(
				"<clear xmlns=\"\"><inside/></clear><inherited/>",
				"xmlns=\"urn:outer:\"");

		Document document = parseFragment(literal.stringValue());
		assertThat(document.getElementsByTagNameNS("", "clear").getLength()).isEqualTo(1);
		assertThat(document.getElementsByTagNameNS("", "inside").getLength()).isEqualTo(1);
		assertThat(document.getElementsByTagNameNS("urn:outer:", "inherited").getLength())
				.as("XMLLiteral: %s", literal.stringValue())
				.isEqualTo(1);
	}

	@Test
	void unusedInheritedPrefixesAreNotAddedToXmlLiteral() throws Exception {
		Literal literal = parseXmlLiteral("<div plain=\"value\"/>", "xmlns:unused=\"urn:unused:\"");

		assertThat(literal.stringValue()).doesNotContain("xmlns:unused=");
		assertThat(parseFragment(literal.stringValue()).getElementsByTagName("div").getLength()).isEqualTo(1);
	}

	private static Literal parseXmlLiteral(String content, String rootNamespaceDeclarations) throws Exception {
		Statement statement = parseXmlLiteralStatement(content, rootNamespaceDeclarations);
		assertThat(statement.getObject()).isInstanceOf(Literal.class);
		Literal literal = (Literal) statement.getObject();
		assertThat(literal.getDatatype()).isEqualTo(RDF.XMLLITERAL);
		return literal;
	}

	private static Statement parseXmlLiteralStatement(String content, String rootNamespaceDeclarations)
			throws Exception {
		String rdfXml = """
				<rdf:RDF xmlns:rdf="%s" xmlns:ex="urn:example:" %s>
				  <rdf:Description rdf:about="urn:subject">
				    <ex:value rdf:parseType="Literal">%s</ex:value>
				  </rdf:Description>
				</rdf:RDF>
				""".formatted(RDF.NAMESPACE, rootNamespaceDeclarations, content);

		Collection<Statement> statements = parse(rdfXml);
		assertThat(statements).hasSize(1);
		return statements.iterator().next();
	}

	private static Collection<Statement> parse(String rdfXml) throws Exception {
		RDFParser parser = Rio.createParser(RDFFormat.RDFXML);
		StatementCollector collector = new StatementCollector();
		parser.setRDFHandler(collector);
		parser.parse(new StringReader(rdfXml), "urn:base:");
		return collector.getStatements();
	}

	private static Document parseFragment(String fragment) throws Exception {
		DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
		factory.setNamespaceAware(true);
		String wrappedFragment = "<fragment>" + fragment + "</fragment>";
		try {
			return factory.newDocumentBuilder().parse(new InputSource(new StringReader(wrappedFragment)));
		} catch (Exception e) {
			throw new AssertionError("XMLLiteral is not a well-formed fragment: " + fragment, e);
		}
	}
}
